                               0..1 : i := 1;
                               2..3 : i := 2;
                               4..7 : i := 3;
                               8..11 : i := 4;
                               12..15 : i := 5
                               else i := 6;
                            end;
                            i := round(i/2);
                            if i = 0 then i := 1;
                            battle[person,2] := i;
                            battle[person,3] := 1;
                         end;
                   3 : begin
                          battle[person,1] := 6;
                          battle[person,2] := 5;
                          j := 1;
                          for i := 1 to enemynumber do
                          if not (enemy[i].unconscious or enemy[i].dead) then j := i;
                          battle[person,3] := j;
                       end;
                end;
            1 : begin
                   j := SelectEnemy;
                   Clear;
                   if j = 0 then battle[person,1] := 0;
                   battle[person,2] := player[person].weapon;
                   battle[person,3] := j;
                end;
            2 : begin
                   for j := 1 to 6 do m[j+1] := ReturnMagic(j);
                   case player[person].level[2] of
                      0..1 : j := 2;
                      2..3 : j := 3;
                      4..7 : j := 4;
                      8..11 : j := 5;
                      12..15 : j := 6
                      else j := 7;
                   end;
                   i := Select(60,j,7,TRUE,FALSE);
                   if (i=0) or (i=1) then battle[person,1] := 0 else j := SelectEnemy;
                   Clear;
                   battle[person,2] := i-1;
                   battle[person,3] := j;
                end;
            3 : begin
                   for j := 1 to 6 do m[j+1] := ReturnMagic(j+6);
                   case player[person].level[2] of
                      0..1 : j := 1;
                      2 : j := 2;
                      3..5 : j := 3;
                      6..9 : j := 4;
                      10..13 : j := 5;
                      14..17 : j := 6
                      else j := 7;
                   end;
                   i := Select(60,j,7,TRUE,TRUE);
                   if (i=0) or (i=1) then battle[person,1] := 0;
                   battle[person,2] := i-1;
                   battle[person,3] := 0;
                end;
            4 : begin
                   for j := 1 to 6 do m[j+1] := ReturnMagic(j+12);
