         clear;
         case upcase(c) of
            'P' : ViewParty;
            'V' : ViewCharacter;
            'Q' : QuickView;
            'C' : CastSpell;
            'E' : Extrasense;
            'R' : Rest;
            'G' : GameOption;
         end;
         x1 := 0; y1 := 0;
         ok := true;
      end;
      if c = #0 then begin
         ok := false;
         c := ReadKey;
         if c in [#72,#75,#77,#80] then ok := true;
         case c of
            #72 : begin
                     y1 := -1;
                     if position = town then face := 1 else face := 5;
                  end;
            #80 : begin
                     y1 := 1;
                     if position = town then face := 0 else face := 4;
                  end;
            #75 : begin
                     x1 := -1;
                     if position = town then face := 3 else face := 7;
                  end;
            #77 : begin
                     x1 := 1;
                     if position = town then face := 2 else face := 6;
                  end;
         end;
         if party.map = 26 then face := face + 4;
      end;
      if c = #32 then begin
         party.etc[6] := 0;
         SelectMode;
         x1 := 0; y1 := 0;
         ok := true;
      end;
      if c = #9 then
      asm
         mov ah,16;
         mov al,27;
         mov bx,0;
         mov cx,255;
         int $10;
      end;
      if c = #8 then soundon := not soundon;
      if c = #255 then for i := 5 to 246 do font^[0,i] := 0;
      if ok then begin
         x := x+x1;
         y := y+y1;
         if (x>4) and (x<xmax-3) and (y>4) and (y<ymax-3) and (c<>#27) then begin

            if position = town then
            case map[x,y] of
               0 : specialevent;
               1..21 : originposition;
